import { SignalRoom } from "./room";

export { SignalRoom };

// Room ids are random and generated by the PC (base64url, 22 chars today).
const ROOM_PATH = /^\/room\/([A-Za-z0-9_-]{16,64})$/;

export default {
	async fetch(request, env): Promise<Response> {
		const url = new URL(request.url);
		if (url.pathname === "/health") return new Response("gocast signal ok");

		const match = ROOM_PATH.exec(url.pathname);
		if (!match) return new Response("Not found", { status: 404 });
		if (request.headers.get("Upgrade")?.toLowerCase() !== "websocket") {
			return new Response("Expected a WebSocket upgrade", { status: 426 });
		}
		const role = url.searchParams.get("role");
		if (role !== "pc" && role !== "phone") {
			return new Response("role must be pc or phone", { status: 400 });
		}
		const room = env.ROOMS.get(env.ROOMS.idFromName(match[1]!));
		return room.fetch(request);
	},
} satisfies ExportedHandler<Env>;
